select type, count(*) from trans group by 1;
select a4, pg_typeof(a4) from district limit 3;
select count(*), count(distinct account_id) from "order";

with a as (select ha.attribute_value v from hero_attribute ha join attribute at on at.id=ha.attribute_id join superhero s on s.id=ha.hero_id where s.superhero_name='Abomination')
select (select v from a) v, count(*), count(s.weight_kg), count(nullif(s.weight_kg,0)), round(avg(s.weight_kg),2), round(avg(nullif(s.weight_kg,0)),2)
from hero_attribute ha join attribute at on at.id=ha.attribute_id join superhero s on s.id=ha.hero_id where ha.attribute_value=(select v from a)
